volatile uint32_t g_pfb_dbg_signal_fail  = 0;
volatile uint32_t g_pfb_dbg_wait_calls   = 0;
#endif

void OSWrappers::signalVSync()
{
#ifndef RELEASE_BUILD
    g_pfb_dbg_signal_calls++;
#endif
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    BaseType_t s = xQueueSendFromISR((QueueHandle_t)vsync_queue, &dummy, &xHigherPriorityTaskWoken);
#ifndef RELEASE_BUILD
    if (s == pdTRUE) g_pfb_dbg_signal_ok++;
    else             g_pfb_dbg_signal_fail++;
#endif
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

